local BulbPlanterMaker = {}
local PRODUCTS = {
    iron_bulbplanter = { name = "Železni sadičnik za čebulnice", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni sadičnik za čebulnice za vrtnarje." },
    bronze_bulbplanter = { name = "Bronast sadičnik za čebulnice", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast sadičnik za čebulnice za vrtnarje." },
    silver_bulbplanter = { name = "Srebrn sadičnik za čebulnice", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn sadičnik za čebulnice za vrtnarje." },
    gilded_bulbplanter = { name = "Pozlačen sadičnik za čebulnice", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen sadičnik za čebulnice za vrtnarje." },
    jewel_set_bulbplanter = { name = "Draguljast sadičnik za čebulnice", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast sadičnik za čebulnice za vrtnarje." },
    royal_sovereign_bulbplanter = { name = "Kraljevski suveren sadičnik za čebulnice", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren sadičnik za čebulnice z biseri za krono." },
}
local BUILDINGS = {
    bulbplanter_workshop = { name = "Bulbplanter delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    bulbplanter_house = { name = "Bulbplanter hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_bulbplanter_atelier = { name = "Mojstrski bulbplanter atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_bulbplanter_palace = { name = "Suverena bulbplanter palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
BulbPlanterMaker.ironStock=16; BulbPlanterMaker.bronzeStock=12; BulbPlanterMaker.woodStock=12; BulbPlanterMaker.leatherStock=8; BulbPlanterMaker.silverStock=8; BulbPlanterMaker.goldStock=6; BulbPlanterMaker.jewelStock=4; BulbPlanterMaker.pearlStock=4
BulbPlanterMaker.productStock = {}; BulbPlanterMaker.buildings = {}; BulbPlanterMaker.maker = nil; BulbPlanterMaker.activeMaking = {}; BulbPlanterMaker.totalProducts = 0; BulbPlanterMaker.dayTimer = 0
function BulbPlanterMaker.init() BulbPlanterMaker.ironStock=16; BulbPlanterMaker.bronzeStock=12; BulbPlanterMaker.woodStock=12; BulbPlanterMaker.leatherStock=8; BulbPlanterMaker.silverStock=8; BulbPlanterMaker.goldStock=6; BulbPlanterMaker.jewelStock=4; BulbPlanterMaker.pearlStock=4; BulbPlanterMaker.productStock={}; BulbPlanterMaker.buildings={}; BulbPlanterMaker.maker=nil; BulbPlanterMaker.activeMaking={}; BulbPlanterMaker.totalProducts=0; BulbPlanterMaker.dayTimer=0; print("[BulbPlanterMaker] Royal Bulb Planter Maker System initialized (6 products, 4 buildings)") end
function BulbPlanterMaker.hireMaker(n,s) s=s or math.random(55,90); local c=580+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; BulbPlanterMaker.maker={name=n or ("Čebuljar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Čebuljar najet: %s (spretnost: %d)",BulbPlanterMaker.maker.name,s),"success") end; return true end
function BulbPlanterMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function BulbPlanterMaker.build(id) local ok,e=BulbPlanterMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(BulbPlanterMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function BulbPlanterMaker.getQualityBonus() local b=0; for _,bd in ipairs(BulbPlanterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function BulbPlanterMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and BulbPlanterMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and BulbPlanterMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and BulbPlanterMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and BulbPlanterMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and BulbPlanterMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and BulbPlanterMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and BulbPlanterMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and BulbPlanterMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #BulbPlanterMaker.buildings==0 then return false,"Potrebna čebulna delavnica" end; if not BulbPlanterMaker.maker then return false,"Potreben čebuljar" end; return true end
function BulbPlanterMaker.make(pt,qty) qty=qty or 1; local ok,e=BulbPlanterMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then BulbPlanterMaker.ironStock=BulbPlanterMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then BulbPlanterMaker.bronzeStock=BulbPlanterMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then BulbPlanterMaker.woodStock=BulbPlanterMaker.woodStock-d.woodCost*qty end; if d.leatherCost then BulbPlanterMaker.leatherStock=BulbPlanterMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then BulbPlanterMaker.silverStock=BulbPlanterMaker.silverStock-d.silverCost*qty end; if d.goldCost then BulbPlanterMaker.goldStock=BulbPlanterMaker.goldStock-d.goldCost*qty end; if d.jewelCost then BulbPlanterMaker.jewelStock=BulbPlanterMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then BulbPlanterMaker.pearlStock=BulbPlanterMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if BulbPlanterMaker.maker then t=math.max(1,t-math.floor(BulbPlanterMaker.maker.skill/13)) end; table.insert(BulbPlanterMaker.activeMaking,{id="bulbplanter_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function BulbPlanterMaker.completeMaking(m) local q=1.0+(BulbPlanterMaker.getQualityBonus()/100); if BulbPlanterMaker.maker then q=q+(BulbPlanterMaker.maker.skill/140) end; q=math.min(2.5,q); BulbPlanterMaker.productStock[m.productType]=(BulbPlanterMaker.productStock[m.productType] or 0)+m.quantity; BulbPlanterMaker.totalProducts=BulbPlanterMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if BulbPlanterMaker.maker then BulbPlanterMaker.maker.itemsMade=BulbPlanterMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then BulbPlanterMaker.maker.skill=math.min(100,BulbPlanterMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Sadičnik izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"bulbplanter.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function BulbPlanterMaker.update(dt) if not _G.state then return end; BulbPlanterMaker.dayTimer=BulbPlanterMaker.dayTimer+dt; if BulbPlanterMaker.dayTimer>=30 then BulbPlanterMaker.dayTimer=0; for i=#BulbPlanterMaker.activeMaking,1,-1 do local m=BulbPlanterMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then BulbPlanterMaker.completeMaking(m); table.remove(BulbPlanterMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(BulbPlanterMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if BulbPlanterMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function BulbPlanterMaker.getStats() return {ironStock=BulbPlanterMaker.ironStock,bronzeStock=BulbPlanterMaker.bronzeStock,woodStock=BulbPlanterMaker.woodStock,leatherStock=BulbPlanterMaker.leatherStock,silverStock=BulbPlanterMaker.silverStock,goldStock=BulbPlanterMaker.goldStock,jewelStock=BulbPlanterMaker.jewelStock,pearlStock=BulbPlanterMaker.pearlStock,productStock=BulbPlanterMaker.productStock,numBuildings=#BulbPlanterMaker.buildings,hasMaker=BulbPlanterMaker.maker~=nil,makerName=BulbPlanterMaker.maker and BulbPlanterMaker.maker.name or "—",makerSkill=BulbPlanterMaker.maker and BulbPlanterMaker.maker.skill or 0,activeMaking=#BulbPlanterMaker.activeMaking,totalProducts=BulbPlanterMaker.totalProducts} end
return BulbPlanterMaker
